import type { ExpoConfig, ConfigContext } from "expo/config";

/** Native configuration is generated by Expo; never embed API credentials here. */
export default ({ config }: ConfigContext): ExpoConfig => {
  const development = process.env.APP_VARIANT === "development";
  return {
    ...config,
    name: development ? "OpenCuria Dev" : "OpenCuria",
    slug: "opencuria",
    version: "0.1.0",
    scheme: "opencuria",
    orientation: "default",
    userInterfaceStyle: "automatic",
    icon: "./assets/icon.png",
    ios: {
      bundleIdentifier: development
        ? "org.opencuria.mobile.dev"
        : "org.opencuria.mobile",
      supportsTablet: true,
      infoPlist: {
        NSCameraUsageDescription:
          "Attach a photo to your OpenCuria conversation.",
        NSPhotoLibraryUsageDescription:
          "Choose photos to share with your OpenCuria agent.",
        ...(development
          ? { NSAppTransportSecurity: { NSAllowsLocalNetworking: true } }
          : {}),
      },
    },
    android: {
      package: development
        ? "org.opencuria.mobile.dev"
        : "org.opencuria.mobile",
      adaptiveIcon: {
        foregroundImage: "./assets/adaptive-icon.png",
        backgroundColor: "#F4F4F6",
      },
      permissions: ["CAMERA"],
      blockedPermissions: ["android.permission.RECORD_AUDIO"],
    },
    plugins: [
      "expo-router",
      "expo-secure-store",
      [
        "expo-image-picker",
        {
          photosPermission: "Choose photos to share with your OpenCuria agent.",
          cameraPermission: "Attach a photo to your OpenCuria conversation.",
          microphonePermission: false,
        },
      ],
      [
        "expo-build-properties",
        { android: { usesCleartextTraffic: development } },
      ],
      "react-native-enriched-markdown",
    ],
    experiments: { typedRoutes: true },
  };
};
